pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] memory _tos, uint[] memory v) public {
        vm.assume(_tos.length > 0);
        vm.assume(v.length == _tos.length);
        vm.assume(caddress != address(c));
        // Deploy a contract that always reverts to simulate a failing external call
        RevertingContract revertContract = new RevertingContract();
        // Use the reverting contract as the target caddress
        bool refResult = c.transfer(from, address(revertContract), _tos, v);
        // The reference should still return true because require(_s) will revert the whole transaction on failure,
        // so if it returns at all, it must be true.
        // The buggy version uses transfer instead of transferFrom, but the revert helper still reverts on any call,
        // so both should revert. We need a scenario where P succeeds and M fails, or both succeed but return different values.
        // Since the difference is about selector, we need a contract that implements transfer but not transferFrom.
        // The adversarial helper should implement transfer but reject calls it doesn't recognize.
        // Actually, the difference: P calls transferFrom, M calls transfer. If caddress doesn't implement transferFrom,
        // the low-level call returns false, causing P to revert. M calls transfer, which might also fail if not implemented.
        // To make P succeed, caddress must implement transferFrom. To make M fail or return false, caddress must not implement transfer.
        // But we want P to succeed and M to fail/revert. So deploy a helper that implements transferFrom but not transfer.
        // Then P succeeds and returns true, M's call to transfer fails and reverts (because of require(_s)).
        // This produces a revert difference: P completes, M reverts.
        address addr = address(new TransferFromOnly());
        bool okP;
        try c.transfer(from, addr, _tos, v) returns (bool r) { okP = true; } catch { okP = false; }
        // For P (reference), this should succeed because TransferFromOnly implements transferFrom.
        // For M (buggy), it calls transfer which is not implemented, so it reverts.
        assertTrue(okP);
    }
}

contract TransferFromOnly {
    // Implements transferFrom but not transfer
    function transferFrom(address from, address to, uint256 amount) external pure returns (bool) {
        return true;
    }
    // No fallback, so transfer will fail (selector mismatch -> call returns false, then require(_s) reverts)
}

