pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address[] memory _tos, uint[] memory v, bool subcallReverts) public {
        vm.assume(_tos.length > 0);
        vm.assume(v.length == _tos.length);
        vm.assume(from != address(0));
        // Deploy a helper that either succeeds or reverts on its fallback call to transferFrom
        SubcallHelper helper = new SubcallHelper(subcallReverts);
        address caddress = address(helper);
        // The helper's fallback will be called via caddress.call(abi.encodeWithSelector(transferFrom, from, to, amount))
        bool ok;
        try c.transfer(from, caddress, _tos, v) {
            ok = true;
        } catch {
            ok = false;
        }
        // Correct behavior: if any subcall reverts, the whole transfer must revert.
        // The helper reverts consistently for all subcalls if subcallReverts is true.
        assertTrue(subcallReverts ? !ok : ok);
    }
}

contract SubcallHelper {
    bool revertOnCall;
    constructor(bool _revertOnCall) { revertOnCall = _revertOnCall; }
    fallback() external payable {
        if (revertOnCall) {
            revert();
        }
    }
}

