import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address[] memory _tos, uint256[] memory v, bool[] memory revertFlags) public {
        vm.assume(_tos.length > 0);
        vm.assume(v.length == _tos.length);
        vm.assume(revertFlags.length == _tos.length);
        address helper = address(new RevertingHelper(revertFlags));
        bool ok;
        try c.transfer(from, helper, _tos, v) returns (bool ret) {
            ok = true;
        } catch {
            ok = false;
        }
        // For the reference, if any sub-call reverts, the whole transfer must revert => ok == false.
        // The buggy version ignores failures and returns true => ok == true.
        // The invariant is: if any revert flag is true, then transfer must have reverted.
        bool anyRevert = false;
        for (uint i = 0; i < revertFlags.length; i++) {
            if (revertFlags[i]) {
                anyRevert = true;
                break;
            }
        }
        assertTrue(!anyRevert || !ok);
    }
}

contract RevertingHelper {
    bool[] public revertFlags;
    constructor(bool[] memory _revertFlags) { revertFlags = _revertFlags; }
    function transferFrom(address, address, uint256) external view returns (bool) {
        uint256 idx;
        assembly { idx := tload(0) }
        assembly { tstore(0, add(idx, 1)) }
        if (revertFlags[idx]) {
            revert("forced revert");
        }
        return true;
    }
}

