pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caller, address caddress, address[] memory _tos, uint[] memory v) public {
        vm.assume(from != caller);
        vm.assume(_tos.length > 0);
        vm.assume(_tos.length == v.length);
        vm.assume(caddress != address(0));

        // Deploy an adversarial ERC20 token that records who transferFrom was called on behalf of
        WrappedERC20 t = new WrappedERC20();
        caddress = address(t);

        // The caller initiates the transaction
        vm.prank(caller);
        bool ok = false;
        try c.transfer(from, caddress, _tos, v) returns (bool r) {
            ok = r;
        } catch {
            ok = false;
        }

        // After the call, the source address recorded by the token must match the 'from' parameter
        // if the transfer succeeded. The buggy version uses msg.sender, so it will record caller instead
        // when caller != from, violating this rule.
        assertTrue(!ok || t.lastFrom() == from);
    }
}

contract WrappedERC20 {
    address public lastFrom;

    // Simplified transferFrom that always succeeds and records the `from` argument
    function transferFrom(address from, address, uint256) external returns (bool) {
        lastFrom = from;
        return true;
    }
}

